mapper.sql:
WHERE s.deleted = 0

    AND s.production_order_no = #{reqVO.productionOrderNo}


    AND s.assembly_material_no = #{reqVO.assemblyMaterialNo}

WITH base_orders AS ( SELECT /*+ MATERIALIZE */ s.production_order_no, s.assembly_material_no, s.main_material_desc, s.scheduled_quantity, s.scheduled_date FROM sub_order s
), plan_agg AS ( SELECT mp.production_order_no, mp.assembly_material_no, MIN(mp.scheduled_date) AS scheduled_date FROM aps_main_plan mp JOIN ( SELECT DISTINCT production_order_no, assembly_material_no FROM base_orders ) bo ON bo.production_order_no = mp.production_order_no AND bo.assembly_material_no = mp.assembly_material_no WHERE mp.deleted = 0 GROUP BY mp.production_order_no, mp.assembly_material_no ), scoped_orders AS ( SELECT /*+ MATERIALIZE */ bo.production_order_no, bo.assembly_material_no, bo.main_material_desc, bo.scheduled_quantity, NVL(mp.scheduled_date, bo.scheduled_date) AS effective_scheduled_date FROM base_orders bo LEFT JOIN plan_agg mp ON mp.production_order_no = bo.production_order_no AND mp.assembly_material_no = bo.assembly_material_no WHERE NVL(mp.scheduled_date, bo.scheduled_date) >= #{reqVO.scheduledDateStart} AND NVL(mp.scheduled_date, bo.scheduled_date) <= #{reqVO.scheduledDateEnd} ), material_agg AS ( SELECT material_no, MAX(material_desc) AS material_desc, MAX(procurement_type) AS procurement_type FROM material_master_import WHERE deleted = 0 GROUP BY material_no ), demand_agg AS ( SELECT so.production_order_no, so.assembly_material_no, so.main_material_desc, so.scheduled_quantity, so.effective_scheduled_date, tod.material_no, MAX(tod.material_description) AS material_description, SUM(NVL(tod.demand_quantity, 0)) AS demand_quantity, SUM(NVL(tod.outbound_accumulated, 0)) AS invested_quantity, mm.material_desc, mm.procurement_type FROM scoped_orders so JOIN trace_order_demand tod ON tod.order_no = so.production_order_no JOIN material_agg mm ON mm.material_no = tod.material_no WHERE tod.deleted = 0 AND mm.procurement_type IN ('E', 'F')
AND tod.material_no = #{reqVO.componentMaterialNo}
AND mm.procurement_type = #{reqVO.procurementType}
GROUP BY so.production_order_no, so.assembly_material_no, so.main_material_desc, so.scheduled_quantity, so.effective_scheduled_date, tod.material_no, mm.material_desc, mm.procurement_type )

mapper.select:
WITH stock AS ( SELECT material_no, SUM(NVL(stock_quantity, 0)) AS stock_quantity FROM real_time_stock WHERE deleted = 0 AND material_no IN
#{materialNo}
GROUP BY material_no ), prod AS ( SELECT assembly_material_no, SUM(GREATEST(NVL(scheduled_quantity, 0) - NVL(delivered_quantity, 0), 0)) AS production_transit FROM sub_order WHERE deleted = 0 AND (system_status LIKE 'CRTD%' OR system_status LIKE 'REL%') AND assembly_material_no IN
#{materialNo}
GROUP BY assembly_material_no ) SELECT NVL(stock.material_no, prod.assembly_material_no) AS materialNo, NVL(stock.stock_quantity, 0) AS stockQuantity, NVL(prod.production_transit, 0) AS productionTransit FROM stock FULL OUTER JOIN prod ON prod.assembly_material_no = stock.material_no
